'use client'

import type { Outfit } from '@/lib/types'
import { Card } from '@/components/ui/card'

interface SimilarOutfitsProps {
  outfits: Outfit[]
  onSelectOutfit: (outfit: Outfit) => void
}

/**
 * Renders a grid of product thumbnails as fallback when no outfit image is available
 */
function ProductThumbnailGrid({ outfit }: { outfit: Outfit }) {
  const items = outfit.items.slice(0, 4)
  if (items.length === 0) {
    return <div className="w-full h-full bg-gray-200 flex items-center justify-center">
      <span className="text-gray-400 text-xs">No items</span>
    </div>
  }

  return (
    <div className={`w-full h-full grid ${items.length === 1 ? 'grid-cols-1' : 'grid-cols-2'} gap-0.5 bg-gray-100`}>
      {items.map((item, index) => (
        <div key={item.sku || index} className="bg-gray-50 overflow-hidden">
          {item.imageUrl ? (
            <img
              src={item.imageUrl}
              alt={item.name}
              className="w-full h-full object-cover"
            />
          ) : (
            <div className="w-full h-full bg-gray-200 flex items-center justify-center">
              <span className="text-gray-400 text-[10px] text-center px-1 line-clamp-2">{item.name}</span>
            </div>
          )}
        </div>
      ))}
    </div>
  )
}

export function SimilarOutfits({ outfits, onSelectOutfit }: SimilarOutfitsProps) {
  if (outfits.length === 0) return null

  return (
    <div className="mt-6 pb-4">
      <h3 className="font-medium mb-3">Similar outfits</h3>

      <div className="grid grid-cols-2 gap-3">
        {outfits.slice(0, 6).map((outfit) => {
          // Only use flat-lay images, not single product imageUrl
          const flatLayImage = outfit.flatLayImageUrl || outfit.flatLayImageBase64

          return (
            <Card
              key={outfit.id}
              className="cursor-pointer hover:shadow-md transition-shadow overflow-hidden"
              onClick={() => onSelectOutfit(outfit)}
            >
              <div className="aspect-[3/4] bg-gray-100">
                {flatLayImage ? (
                  <img
                    src={flatLayImage}
                    alt={outfit.title}
                    className="w-full h-full object-contain"
                  />
                ) : (
                  <ProductThumbnailGrid outfit={outfit} />
                )}
              </div>

              <div className="p-2">
                <p className="text-xs font-medium line-clamp-1">{outfit.title}</p>
                <p className="text-xs text-primary font-bold mt-1">
                  ฿{outfit.totalPrice.toLocaleString()}
                </p>
              </div>
            </Card>
          )
        })}
      </div>
    </div>
  )
}

