     1→/**
     2→ * Image Generation Service
     3→ * Client for OpenRouter API using Gemini 2.5 Flash Preview Image model for outfit visualization
     4→ *
     5→ * Features:
     6→ * - Fashion-specific prompt engineering
     7→ * - Error handling with retries
     8→ * - Timeout protection
     9→ * - Rate limiting awareness
    10→ */
    11→
    12→import type { ImageGenerationRequest, ImageGenerationResponse, FlatLayRequest, FlatLayItem } from '../types/image-types';
    13→
    14→/**
    15→ * OpenRouter API configuration
    16→ */
    17→const OPENROUTER_CONFIG = {
    18→  /** OpenRouter API base URL */
    19→  baseUrl: 'https://openrouter.ai/api/v1',
    20→  /**
    21→   * Model ID for Gemini 3 Pro Image Preview - Nano Banana Pro (text-to-image capable)
    22→   * Google's most advanced image-generation and editing model
    23→   */
    24→  model: 'google/gemini-2.5-flash-image',
    25→  /** Request timeout in milliseconds */
    26→  timeout: 30000,
    27→  /** Maximum retry attempts on failure */
    28→  maxRetries: 2,
    29→  /** Exponential backoff base delay (ms) */
    30→  retryDelay: 1000,
    31→};
    32→
    33→/**
    34→ * OpenRouter Image Generation Client
    35→ * Handles communication with OpenRouter API for outfit image generation
    36→ */
    37→export class OpenRouterImageClient {
    38→  private apiKey: string;
    39→  private requestCount: number = 0;
    40→  private lastRequestTime: number = 0;
    41→
    42→  /**
    43→   * Creates a new OpenRouter image client
    44→   *
    45→   * @param apiKey - OpenRouter API key
    46→   * @throws Error if API key is not provided
    47→   */
    48→  constructor(apiKey: string) {
    49→    if (!apiKey || typeof apiKey !== 'string' || apiKey.trim() === '') {
    50→      throw new Error('OpenRouter API key is required');
    51→    }
    52→    this.apiKey = apiKey;
    53→  }
    54→
    55→  /**
    56→   * Configuration for fitting model generation
    57→   */
    58→  private static readonly FITTING_MODEL_CONFIG = {
    59→    /** Extended timeout for fitting model generation (60 seconds) */
    60→    timeout: 60000,
    61→  };
    62→
    63→  /**
    64→   * Generates an outfit image from description using Gemini 2.5 Flash Preview
    65→   *
    66→   * @param description - Outfit description extracted from conversation
    67→   * @param options - Optional style parameters
    68→   * @returns Promise resolving to image generation response
    69→   *
    70→   * @example
    71→   * const client = new OpenRouterImageClient(apiKey);
    72→   * const response = await client.generateOutfitImage(
    73→   *   "White shirt with black pants for business meeting",
    74→   *   { style: { composition: 'flat-lay' } }
    75→   * );
    76→   */
    77→  async generateOutfitImage(
    78→    description: string,
    79→    options?: ImageGenerationRequest['style']
    80→  ): Promise<ImageGenerationResponse> {
    81→    // Validate input
    82→    if (!description || typeof description !== 'string' || description.trim() === '') {
    83→      return {
    84→        success: false,
    85→        error: 'INVALID_DESCRIPTION',
    86→        message: 'Outfit description is required',
    87→      };
    88→    }
    89→
    90→    // Check client-side rate limiting (basic protection)
    91→    if (!this.checkRateLimit()) {
    92→      return {
    93→        success: false,
    94→        error: 'RATE_LIMITED',
    95→        message: 'Too many requests. Please wait a moment before trying again.',
    96→      };
    97→    }
    98→
    99→    // Attempt generation with retries
   100→    let lastError: Error | null = null;
   101→
   102→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   103→      try {
   104→        if (attempt > 0) {
   105→          // Exponential backoff delay
   106→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   107→          await this.sleep(delay);
   108→          console.log(`[ImageGen] Retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   109→        }
   110→
   111→        const result = await this.makeRequest(description, options);
   112→        return result;
   113→      } catch (error) {
   114→        lastError = error as Error;
   115→        console.error(`[ImageGen] Attempt ${attempt + 1} failed:`, error);
   116→
   117→        // Don't retry on certain errors
   118→        if (this.isNonRetryableError(error)) {
   119→          break;
   120→        }
   121→      }
   122→    }
   123→
   124→    // All retries failed
   125→    return {
   126→      success: false,
   127→      error: 'GENERATION_FAILED',
   128→      message: 'Unable to generate image. Please try again later.',
   129→    };
   130→  }
   131→
   132→  /**
   133→   * Generates a fitting model image using a reference image for face-matching.
   134→   * Uses OpenRouter's multimodal content format to pass the reference image.
   135→   *
   136→   * @param prompt - Fitting model generation prompt with style requirements
   137→   * @param referenceImageBase64 - Base64 encoded reference image (with data URL prefix)
   138→   * @returns Promise resolving to image generation response
   139→   *
   140→   * @example
   141→   * const client = new OpenRouterImageClient(apiKey);
   142→   * const response = await client.generateFittingModelImage(
   143→   *   "Create a photorealistic fitting model...",
   144→   *   "data:image/jpeg;base64,/9j/4AAQ..."
   145→   * );
   146→   */
   147→  async generateFittingModelImage(
   148→    prompt: string,
   149→    referenceImageBase64: string
   150→  ): Promise<ImageGenerationResponse> {
   151→    // Validate inputs
   152→    if (!prompt || typeof prompt !== 'string' || prompt.trim() === '') {
   153→      return {
   154→        success: false,
   155→        error: 'INVALID_PROMPT',
   156→        message: 'Fitting model prompt is required',
   157→      };
   158→    }
   159→
   160→    if (!referenceImageBase64 || typeof referenceImageBase64 !== 'string' || referenceImageBase64.trim() === '') {
   161→      return {
   162→        success: false,
   163→        error: 'INVALID_REFERENCE_IMAGE',
   164→        message: 'Reference image is required for fitting model generation',
   165→      };
   166→    }
   167→
   168→    if (!referenceImageBase64.startsWith('data:image/')) {
   169→      return {
   170→        success: false,
   171→        error: 'INVALID_REFERENCE_IMAGE_FORMAT',
   172→        message: 'Reference image must be a base64 data URL (e.g., data:image/jpeg;base64,...)',
   173→      };
   174→    }
   175→
   176→    // Check client-side rate limiting
   177→    if (!this.checkRateLimit()) {
   178→      return {
   179→        success: false,
   180→        error: 'RATE_LIMITED',
   181→        message: 'Too many requests. Please wait a moment before trying again.',
   182→      };
   183→    }
   184→
   185→    // Attempt generation with retries
   186→    let lastError: Error | null = null;
   187→
   188→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   189→      try {
   190→        if (attempt > 0) {
   191→          // Exponential backoff delay
   192→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   193→          await this.sleep(delay);
   194→          console.log(`[ImageGen] Fitting model retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   195→        }
   196→
   197→        const result = await this.makeFittingModelRequest(prompt, referenceImageBase64);
   198→        return result;
   199→      } catch (error) {
   200→        lastError = error as Error;
   201→        console.error(`[ImageGen] Fitting model attempt ${attempt + 1} failed:`, error);
   202→
   203→        // Don't retry on certain errors
   204→        if (this.isNonRetryableError(error)) {
   205→          break;
   206→        }
   207→      }
   208→    }
   209→
   210→    // All retries failed
   211→    return {
   212→      success: false,
   213→      error: 'GENERATION_FAILED',
   214→      message: 'Unable to generate fitting model image. Please try again later.',
   215→    };
   216→  }
   217→
   218→  /**
   219→   * Generates a flat-lay image showing recommended items individually placed on a white background.
   220→   *
   221→   * @param request - Flat-lay request containing items to display
   222→   * @returns Promise resolving to image generation response
   223→   *
   224→   * @example
   225→   * const client = new OpenRouterImageClient(apiKey);
   226→   * const response = await client.generateFlatLayImage({
   227→   *   items: [
   228→   *     { name: 'Navy blue button-front dress', category: 'Dress', color: 'navy blue' },
   229→   *     { name: 'Black leather oxford shoes', category: 'Shoes', color: 'black' }
   230→   *   ],
   231→   *   occasionContext: 'work outfit'
   232→   * });
   233→   */
   234→  async generateFlatLayImage(
   235→    request: FlatLayRequest
   236→  ): Promise<ImageGenerationResponse> {
   237→    // Validate inputs
   238→    if (!request.items || !Array.isArray(request.items) || request.items.length === 0) {
   239→      return {
   240→        success: false,
   241→        error: 'INVALID_ITEMS',
   242→        message: 'At least one item is required for flat-lay generation',
   243→      };
   244→    }
   245→
   246→    // Check client-side rate limiting
   247→    if (!this.checkRateLimit()) {
   248→      return {
   249→        success: false,
   250→        error: 'RATE_LIMITED',
   251→        message: 'Too many requests. Please wait a moment before trying again.',
   252→      };
   253→    }
   254→
   255→    // Attempt generation with retries
   256→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   257→      try {
   258→        if (attempt > 0) {
   259→          // Exponential backoff delay
   260→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   261→          await this.sleep(delay);
   262→          console.log(`[ImageGen] Flat-lay retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   263→        }
   264→
   265→        const prompt = this.buildFlatLayPrompt(request.items, request.occasionContext);
   266→        const result = await this.makeFlatLayRequest(prompt);
   267→        return result;
   268→      } catch (error) {
   269→        console.error(`[ImageGen] Flat-lay attempt ${attempt + 1} failed:`, error);
   270→
   271→        // Don't retry on certain errors
   272→        if (this.isNonRetryableError(error)) {
   273→          break;
   274→        }
   275→      }
   276→    }
   277→
   278→    // All retries failed
   279→    return {
   280→      success: false,
   281→      error: 'GENERATION_FAILED',
   282→      message: 'Unable to generate flat-lay image. Please try again later.',
   283→    };
   284→  }
   285→
   286→  /**
   287→   * Builds the flat-lay prompt from item array
   288→   * Based on the format from data/personas/prompt_gen/looks.md
   289→   *
   290→   * @private
   291→   */
   292→  private buildFlatLayPrompt(items: FlatLayItem[], occasionContext?: string): string {
   293→    // Build item descriptions
   294→    const itemDescriptions = items.map((item) => {
   295→      const colorInfo = item.color ? `${item.color} ` : '';
   296→      const description = item.visualDescription || `${colorInfo}${item.name}`;
   297→      return `- ${item.category}: ${description}`;
   298→    }).join('\n');
   299→
   300→    // Build occasion context if provided
   301→    const contextLine = occasionContext
   302→      ? `\nOCCASION CONTEXT: ${occasionContext}\n`
   303→      : '';
   304→
   305→    const prompt = `
   306→Generate an accurate flat-lay fashion image with the following items individually placed and separated, styled in an elegant composition on a white background:
   307→
   308→${itemDescriptions}
   309→${contextLine}
   310→REQUIREMENTS:
   311→- Each item should be clearly visible and properly sized relative to each other
   312→- Items should be laid out in an organized, aesthetically pleasing arrangement
   313→- Clean white background
   314→- Professional product photography quality
   315→- Sharp focus on all items
   316→- Accurate color representation
   317→- High-end fashion editorial style
   318→- Items should not overlap
   319→
   320→COMPOSITION:
   321→- Square format (1:1 aspect ratio)
   322→- Flat-lay perspective (top-down view)
   323→- Balanced spacing between items
   324→- Elegant, minimalist styling
   325→`.trim();
   326→
   327→    return prompt;
   328→  }
   329→
   330→  /**
   331→   * Makes API request to OpenRouter for flat-lay generation
   332→   *
   333→   * @private
   334→   */
   335→  private async makeFlatLayRequest(prompt: string): Promise<ImageGenerationResponse> {
   336→    // Build request body
   337→    const requestBody = {
   338→      model: OPENROUTER_CONFIG.model,
   339→      messages: [
   340→        {
   341→          role: 'user',
   342→          content: prompt,
   343→        },
   344→      ],
   345→      modalities: ['text', 'image'], // Required for image generation
   346→      max_tokens: 4096,
   347→    };
   348→
   349→    console.log('[ImageGen] Sending flat-lay request to OpenRouter:', {
   350→      model: requestBody.model,
   351→      promptLength: prompt.length,
   352→    });
   353→
   354→    // Create abort controller for timeout
   355→    const controller = new AbortController();
   356→    const timeoutId = setTimeout(() => controller.abort(), OPENROUTER_CONFIG.timeout);
   357→
   358→    try {
   359→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
   360→        method: 'POST',
   361→        headers: {
   362→          'Content-Type': 'application/json',
   363→          Authorization: `Bearer ${this.apiKey}`,
   364→          'HTTP-Referer': 'https://ootday.com',
   365→          'X-Title': 'OOTDay Fashion Assistant',
   366→        },
   367→        body: JSON.stringify(requestBody),
   368→        signal: controller.signal,
   369→      });
   370→
   371→      clearTimeout(timeoutId);
   372→
   373→      if (!response.ok) {
   374→        const errorData = await response.json().catch(() => ({}));
   375→        throw new Error(
   376→          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
   377→        );
   378→      }
   379→
   380→      const data = await response.json();
   381→
   382→      // Parse response and extract image
   383→      const imageData = this.parseImageResponse(data);
   384→
   385→      return {
   386→        success: true,
   387→        imageBase64: imageData.base64,
   388→        imageUrl: imageData.url,
   389→        metadata: {
   390→          model: OPENROUTER_CONFIG.model,
   391→          generatedAt: new Date().toISOString(),
   392→          prompt: prompt,
   393→        },
   394→        message: 'Flat-lay image generated successfully',
   395→      };
   396→    } catch (error) {
   397→      clearTimeout(timeoutId);
   398→
   399→      if (error instanceof Error) {
   400→        if (error.name === 'AbortError') {
   401→          throw new Error('Request timeout - flat-lay generation took too long');
   402→        }
   403→        throw error;
   404→      }
   405→
   406→      throw new Error('Unknown error during flat-lay generation');
   407→    }
   408→  }
   409→
   410→  /**
   411→   * Generates a try-on image using dual image references:
   412→   * - IMAGE 1 (fitting model): Used to match the person's face and body exactly
   413→   * - IMAGE 2 (flat-lay): Used to show the exact outfit items the model must wear
   414→   *
   415→   * @param prompt - Try-on generation prompt with dual image instructions
   416→   * @param fittingModelBase64 - Base64 encoded fitting model image (with data URL prefix)
   417→   * @param flatLayBase64 - Base64 encoded flat-lay outfit image (with data URL prefix)
   418→   * @returns Promise resolving to image generation response
   419→   */
   420→  async generateTryOnWithDualReference(
   421→    prompt: string,
   422→    fittingModelBase64: string,
   423→    flatLayBase64: string
   424→  ): Promise<ImageGenerationResponse> {
   425→    // Validate inputs
   426→    if (!prompt || typeof prompt !== 'string' || prompt.trim() === '') {
   427→      return {
   428→        success: false,
   429→        error: 'INVALID_PROMPT',
   430→        message: 'Try-on prompt is required',
   431→      };
   432→    }
   433→
   434→    if (!fittingModelBase64 || !fittingModelBase64.startsWith('data:image/')) {
   435→      return {
   436→        success: false,
   437→        error: 'INVALID_FITTING_MODEL_IMAGE',
   438→        message: 'Fitting model image must be a base64 data URL',
   439→      };
   440→    }
   441→
   442→    if (!flatLayBase64 || !flatLayBase64.startsWith('data:image/')) {
   443→      return {
   444→        success: false,
   445→        error: 'INVALID_FLAT_LAY_IMAGE',
   446→        message: 'Flat-lay image must be a base64 data URL',
   447→      };
   448→    }
   449→
   450→    // Check client-side rate limiting
   451→    if (!this.checkRateLimit()) {
   452→      return {
   453→        success: false,
   454→        error: 'RATE_LIMITED',
   455→        message: 'Too many requests. Please wait a moment before trying again.',
   456→      };
   457→    }
   458→
   459→    // Attempt generation with retries
   460→    for (let attempt = 0; attempt <= OPENROUTER_CONFIG.maxRetries; attempt++) {
   461→      try {
   462→        if (attempt > 0) {
   463→          const delay = OPENROUTER_CONFIG.retryDelay * Math.pow(2, attempt - 1);
   464→          await this.sleep(delay);
   465→          console.log(`[ImageGen] Dual reference try-on retry attempt ${attempt}/${OPENROUTER_CONFIG.maxRetries}`);
   466→        }
   467→
   468→        const result = await this.makeDualReferenceRequest(prompt, fittingModelBase64, flatLayBase64);
   469→        return result;
   470→      } catch (error) {
   471→        console.error(`[ImageGen] Dual reference try-on attempt ${attempt + 1} failed:`, error);
   472→
   473→        if (this.isNonRetryableError(error)) {
   474→          break;
   475→        }
   476→      }
   477→    }
   478→
   479→    return {
   480→      success: false,
   481→      error: 'GENERATION_FAILED',
   482→      message: 'Unable to generate try-on image. Please try again later.',
   483→    };
   484→  }
   485→
   486→  /**
   487→   * Makes multimodal API request with TWO reference images for try-on generation
   488→   *
   489→   * @private
   490→   */
   491→  private async makeDualReferenceRequest(
   492→    prompt: string,
   493→    fittingModelBase64: string,
   494→    flatLayBase64: string
   495→  ): Promise<ImageGenerationResponse> {
   496→    // Build multimodal request body with text + 2 images
   497→    // Order: text first, then images (IMAGE 1 = fitting model, IMAGE 2 = flat-lay)
   498→    const requestBody = {
   499→      model: OPENROUTER_CONFIG.model,
   500→      messages: [
   501→        {
   502→          role: 'user',
   503→          content: [
   504→            {
   505→              type: 'text',
   506→              text: prompt,
   507→            },
   508→            {
   509→              type: 'image_url',
   510→              image_url: {
   511→                url: fittingModelBase64,
   512→              },
   513→            },
   514→            {
   515→              type: 'image_url',
   516→              image_url: {
   517→                url: flatLayBase64,
   518→              },
   519→            },
   520→          ],
   521→        },
   522→      ],
   523→      modalities: ['text', 'image'],
   524→      max_tokens: 4096,
   525→    };
   526→
   527→    console.log('[ImageGen] Sending dual reference try-on request to OpenRouter:', {
   528→      model: requestBody.model,
   529→      promptLength: prompt.length,
   530→      hasFittingModelImage: true,
   531→      hasFlatLayImage: true,
   532→    });
   533→
   534→    // Create abort controller with extended timeout
   535→    const controller = new AbortController();
   536→    const timeoutId = setTimeout(
   537→      () => controller.abort(),
   538→      OpenRouterImageClient.FITTING_MODEL_CONFIG.timeout
   539→    );
   540→
   541→    try {
   542→      const response = await fetch(`${OPENROUTER_CONFIG.baseUrl}/chat/completions`, {
   543→        method: 'POST',
   544→        headers: {
   545→          'Content-Type': 'application/json',
   546→          Authorization: `Bearer ${this.apiKey}`,
   547→          'HTTP-Referer': 'https://ootday.com',
   548→          'X-Title': 'OOTDay Fashion Assistant',
   549→        },
   550→        body: JSON.stringify(requestBody),
   551→        signal: controller.signal,
   552→      });
   553→
   554→      clearTimeout(timeoutId);
   555→
   556→      if (!response.ok) {
   557→        const errorData = await response.json().catch(() => ({}));
   558→        throw new Error(
   559→          `OpenRouter API error: ${response.status} - ${errorData.error?.message || response.statusText}`
   560→        );
   561→      }
   562→
   563→      const data = await response.json();
   564→      const imageData = this.parseImageResponse(data);
   565→
   566→      return {
   567→        success: true,
   568→        imageBase64: imageData.base64,
   569→        imageUrl: imageData.url,
   570→        metadata: {
   571→          model: OPENROUTER_CONFIG.model,
   572→          generatedAt: new Date().toISOString(),
   573→          prompt: prompt,
   574→        },
   575→        message: 'Dual reference try-on image generated successfully',
   576→      };
   577→    } catch (error) {
